window.MG_LAZY_DATA["data/lazy/resources/security-v26-022-18cb9594c3f1ce7c.json"]={sha256:"18cb9594c3f1ce7cf18adfce0f8cd0d7d72394ce7c3971b90ae4c99b87b26c0b",value:{"sources":[{"id":"v26-case-39241930ff83b72d","url":"https://docs.netgate.com/pfsense/en/latest/firewall/index.html","title":"pfSense firewall documentation","titleEn":"pfSense firewall documentation","publisher":"Netgate","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"security-v26-022","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"security-v26-022","related":[{"id":"security-v26-023","referenceUrls":["https://www.rfc-editor.org/rfc/rfc9099.html","https://www.rfc-editor.org/rfc/rfc6105.html"],"title":"IPv6 RA Guard：鄰居探索與必要控制流量","titleEn":"IPv6 RA Guard: neighbor discovery and required control traffic","why":"用兩課的可觀察驗收條件比較模型邊界：12000與24000標為穩態期望非設備承諾，守恆核對正確，規則回復方式已記錄。 交付state守恆表、兩種容量估算與規則/NAT診斷分支。","whyEn":"Compare model boundaries using observable acceptance criteria: Label 12000 and 24000 as steady-state estimates rather than appliance guarantees, reconcile state balance and document rollback. Deliver the state-balance table, two capacity estimates and rule/NAT diagnostic branches.","difference":"畫出24個接入埠與2個授權路由器埠；逐埠測RA、NS/NA與必要錯誤通知，不使用「全部封鎖ICMPv6」代替設計。","differenceEn":"Map 24 access ports and two authorized router ports; test RA, NS/NA and required error notifications per port instead of blocking all ICMPv6.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["在穩態且沒有提前回收的簡化模型，平均states≈每秒新連線λ×平均生命W；尖峰與重傳需另留容量。 λ=400個新連線/秒，平均W=30秒；流量平穩且每連線占一個state。 400×30=12000個state；平均生命延至60秒時為24000個。","端口測試數=(接入埠+路由器埠)×封包類別數；允許RA的埠與允許鄰居探索的埠集合不相同。 24個接入埠、2個路由器埠、3類合成控制封包；每類固定一個正常樣本。 (24+2)×3=78案；接入埠增至48而其餘不變時為150案。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["In a simplified steady state without early eviction, average states≈arrival rate λ×mean lifetime W; bursts and retries need separate headroom. λ=400 new connections per second and W=30 seconds, with steady arrivals and one state per connection. 400×30=12000 states; lifetime 60 seconds yields 24000.","Port tests equal (access+router ports)×packet classes; ports allowed to send RA are not the same set as ports needing neighbor discovery. There are 24 access ports, two router ports and three synthetic control-packet classes, with one normal fixture per class. (24+2)×3=78 tests; 48 access ports with other conditions fixed require 150.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"security-v26-032","referenceUrls":["https://learn.microsoft.com/en-us/sysinternals/downloads/sysmon"],"title":"Sysmon：ProcessGuid、父子關係與PID重用","titleEn":"Sysmon: ProcessGuid, parent relationships and PID reuse","why":"用兩課的可觀察驗收條件比較模型邊界：12000與24000標為穩態期望非設備承諾，守恆核對正確，規則回復方式已記錄。 交付state守恆表、兩種容量估算與規則/NAT診斷分支。","whyEn":"Compare model boundaries using observable acceptance criteria: Label 12000 and 24000 as steady-state estimates rather than appliance guarantees, reconcile state balance and document rollback. Deliver the state-balance table, two capacity estimates and rule/NAT diagnostic branches.","difference":"建立兩個在不同時間重用相同PID的無害程序，再以合成ProcessGuid、ParentProcessGuid、主機與時間組樹；明示程序建立和網路事件的關聯鍵。","differenceEn":"Create fictional benign processes reusing one PID at different times, then build trees from ProcessGuid, ParentProcessGuid, host and time; define joins between creation and network events.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["在穩態且沒有提前回收的簡化模型，平均states≈每秒新連線λ×平均生命W；尖峰與重傳需另留容量。 λ=400個新連線/秒，平均W=30秒；流量平穩且每連線占一個state。 400×30=12000個state；平均生命延至60秒時為24000個。","未壓縮事件資料量=事件數×平均位元組；關聯時PID不是長期唯一鍵，ProcessGuid也需保留主機及收集範圍。 教學每日40000個事件，平均900位元組；不含索引、傳輸與複寫。 40000×900=36000000位元組；加入必要事件類型至60000個後為54000000位元組。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["In a simplified steady state without early eviction, average states≈arrival rate λ×mean lifetime W; bursts and retries need separate headroom. λ=400 new connections per second and W=30 seconds, with steady arrivals and one state per connection. 400×30=12000 states; lifetime 60 seconds yields 24000.","Uncompressed event volume equals count×average bytes; PID is not a durable identifier, and ProcessGuid joins retain host and collection scope. A teaching day contains 40000 events averaging 900 bytes, excluding indexing, transport and replication. 40000×900=36000000 bytes; increasing required event count to 60000 yields 54000000 bytes.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v26-case-29019734ff59b23c","url":"https://www.rfc-editor.org/rfc/rfc9099.html","title":"RFC 9099: Operational Security Considerations for IPv6","titleEn":"RFC 9099: Operational Security Considerations for IPv6","publisher":"IETF","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v26-case-60504b65b60bd572","url":"https://www.rfc-editor.org/rfc/rfc6105.html","title":"RFC 6105: IPv6 Router Advertisement Guard","titleEn":"RFC 6105: IPv6 Router Advertisement Guard","publisher":"IETF","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v26-case-b85c6875a5a8f316","url":"https://learn.microsoft.com/en-us/sysinternals/downloads/sysmon","title":"Sysmon documentation","titleEn":"Sysmon documentation","publisher":"Microsoft","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
